import { Component, input, OnInit, inject, ChangeDetectionStrategy, signal, computed } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { KeyValuePipe, UpperCasePipe } from '@angular/common';
import { take } from 'rxjs/operators';
import { QRCodeComponent } from 'angularx-qrcode';
import { Group } from '../../../../../core/interfaces/group';
import { GroupJoinService } from '../../../../../core/services/group-join.service';
import { GroupMemberUserService } from '../../../../../core/services/group-member-user.service';
import { GroupDetailService } from '../../../../../core/services/group-detail.service';
import { DialogService } from '../../../../../shared/dialog/dialog.service';
import { ConfirmDialogComponent } from '../../../../../shared/components/confirm-dialog/confirm-dialog.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { DropdownComponent } from '../../../../../shared/components/dropdown/dropdown.component';
import { TooltipComponent } from '../../../../../shared/components/tooltip/tooltip.component';

@Component({
  selector: 'app-group-share',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [TranslateModule, UpperCasePipe, KeyValuePipe, QRCodeComponent, ButtonComponent, DropdownComponent, TooltipComponent, IconComponent],
  templateUrl: './group-share.component.html',
  styleUrls: ['./group-share.component.scss']
})
export class GroupShareComponent implements OnInit {
  group = input.required<Group>();
  showQR = signal(false);

  private groupJoinService = inject(GroupJoinService);
  private memberUserService = inject(GroupMemberUserService);
  private groupDetailService = inject(GroupDetailService);
  private dialog = inject(DialogService);

  LEVELS = this.memberUserService.LEVELS;

  joinLevel = signal<string>(this.memberUserService.LEVELS.read);
  joinToken = signal<string | null>(null);
  joinUrl = computed(() => {
    const base = window.location.origin;
    const token = this.joinToken();
    const group = this.group();
    if (token && this.groupDetailService.canShare(group)) {
      return `${base}/groups/join/${token}`;
    } else {
      return `${base}/groups/${group.id}/join`;
    }
  });
  copySuccess = signal(false);

  ngOnInit() {
    const group = this.group();
    this.joinToken.set(group.join?.token ?? null);
    this.joinLevel.set(group.join?.level ?? this.memberUserService.LEVELS.read);
  }

  canUpdate() {
    return this.groupDetailService.canUpdate(this.group());
  }


  generateTokenJoin() {
    this.dialog.open(ConfirmDialogComponent, {
      data: {
        title: 'MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_TXT_ARE_YOU_SURE',
        heading: 'MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_HEADING',
        closeBtn: 'MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_BTN_NO',
        confirmBtn: 'MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_BTN_YES',
        points: ['MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_TXT_POINT1', 'MODALS.GROUP_INVITE_SHARE_LINK_GENERATE_CONFIRM_TXT_POINT2']
      }
    }).afterClosed().pipe(take(1)).subscribe(result => {
      if (result === true) {
        this.groupJoinService.generateToken(this.group().id, this.joinLevel())
          .pipe(take(1)).subscribe((res: any) => {
            this.joinToken.set(res.token);
            if (res.level) this.joinLevel.set(res.level);
          });
      }
    });
  }

  doUpdateJoinToken(level: string) {
    const token = this.joinToken();
    if (!token) return;
    this.groupJoinService.updateLevel(this.group().id, token, level)
      .pipe(take(1)).subscribe(() => {
        this.joinLevel.set(level);
      });
  }

  copyInviteLink() {
    const url = this.joinUrl();
    if (url) {
      navigator.clipboard.writeText(url).then(() => {
        this.copySuccess.set(true);
      });
    }
  }
}

import { TestBed } from '@angular/core/testing';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { runInInjectionContext, EnvironmentInjector, signal } from '@angular/core';
import { PublicGroupsComponent } from './public-groups.component';
import { PublicGroupService } from '../../../core/services/public-group.service';
import { UserStore } from '../../../core/state/user.store';
import { provideRouter } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';

const mockGroupService: Partial<PublicGroupService> = {
  items: signal([]),
  totalPages: signal(1),
  reset: vi.fn(),
  setParam: vi.fn(),
  loadPage: vi.fn(),
};

const mockUserStore: { isAuthenticated: any; user: any } = {
  isAuthenticated: vi.fn().mockReturnValue(false) as unknown as () => boolean,
  user: vi.fn().mockReturnValue(null) as unknown as () => null,
};

describe('PublicGroupsComponent', () => {
  let injector: EnvironmentInjector;

  beforeEach(() => {
    vi.clearAllMocks();
    TestBed.configureTestingModule({
      imports: [TranslateModule.forRoot()],
      providers: [
        provideRouter([]),
        { provide: PublicGroupService, useValue: mockGroupService },
        { provide: UserStore, useValue: mockUserStore },
      ],
    });
    injector = TestBed.inject(EnvironmentInjector);
  });

  function makeComp(): PublicGroupsComponent {
    return runInInjectionContext(injector, () => new PublicGroupsComponent());
  }

  it('should instantiate', () => {
    expect(makeComp()).toBeTruthy();
  });

  it('filterConfigs has visibility, orderBy, country, language filters', () => {
    const comp = makeComp();
    const keys = comp.filterConfigs().map(c => c.key);
    expect(keys).toContain('visibility');
    expect(keys).toContain('orderBy');
    expect(keys).toContain('country');
    expect(keys).toContain('language');
  });

  it('visibility filter does not include favourite when not authenticated', () => {
    const comp = makeComp();
    const visFilter = comp.filterConfigs().find(c => c.key === 'visibility')!;
    const values = visFilter.items.map(i => i.value);
    expect(values).not.toContain('favourite');
  });

  it('visibility filter includes favourite when authenticated', () => {
    mockUserStore.isAuthenticated.mockReturnValue(true);
    const comp = makeComp();
    const visFilter = comp.filterConfigs().find(c => c.key === 'visibility')!;
    const values = visFilter.items.map(i => i.value);
    expect(values).toContain('favourite');
  });

  it('onSearch sets search param', () => {
    const comp = makeComp();
    comp.onSearch('public');
    expect(mockGroupService.setParam).toHaveBeenCalledWith('search', 'public');
  });

  it('onFilterChange with orderBy sets params', () => {
    const comp = makeComp();
    comp.onFilterChange({ key: 'orderBy', value: 'memberCount' });
    expect(mockGroupService.reset).toHaveBeenCalled();
    expect(mockGroupService.setParam).toHaveBeenCalledWith('orderBy', 'memberCount');
    expect(mockGroupService.setParam).toHaveBeenCalledWith('order', 'desc');
  });

  it('onFilterChange with visibility favourite sets favourite param', () => {
    const comp = makeComp();
    comp.onFilterChange({ key: 'visibility', value: 'favourite' });
    expect(mockGroupService.reset).toHaveBeenCalled();
    expect(mockGroupService.setParam).toHaveBeenCalledWith('favourite', true);
  });

  it('onPageChange updates currentPage and calls loadPage', () => {
    const comp = makeComp();
    comp.onPageChange(3);
    expect(comp.currentPage()).toBe(3);
    expect(mockGroupService.loadPage).toHaveBeenCalledWith(3);
  });
});

import { MockIconComponent } from '../../shared/testing/mocks';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { HomeComponent } from './home.component';
import { HttpClientTestingModule } from '@angular/common/http/testing';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { provideRouter, Router, RouterLink } from '@angular/router';
import { By } from '@angular/platform-browser';
import { UserStore } from '../../core/state/user.store';
import { PublicTopicService } from '../../core/services/public-topic.service';
import { PublicGroupService } from '../../core/services/public-group.service';
import { HomeService } from './services/home.service';
import { signal, NO_ERRORS_SCHEMA, PLATFORM_ID } from '@angular/core';
import { of } from 'rxjs';
import { describe, it, expect, beforeEach, vi } from 'vitest';

describe('HomeComponent', () => {
  let component: HomeComponent;
  let fixture: ComponentFixture<HomeComponent>;
  let mockUserStore: { isAuthenticated: ReturnType<typeof signal<boolean>> };
  let mockTopicService: { getPreview: any };
  let mockGroupService: { getPreview: any };
  let mockHomeService: Partial<HomeService>;

  beforeEach(async () => {
    mockUserStore = {
      isAuthenticated: signal(false)
    };
    mockTopicService = {
      getPreview: vi.fn().mockReturnValue(of([]))
    };
    mockGroupService = {
      getPreview: vi.fn().mockReturnValue(of([]))
    };
    mockHomeService = {
      getStats: vi.fn().mockReturnValue(of({
        ideasProposed: 10,
        topicsCreated: 20,
        votesCast: 30,
        usersCreated: 40
      }))
    };

    await TestBed.configureTestingModule({
      imports: [HttpClientTestingModule, TranslateModule.forRoot()],
      providers: [
        provideRouter([]),
        { provide: UserStore, useValue: mockUserStore },
        { provide: PublicTopicService, useValue: mockTopicService },
        { provide: PublicGroupService, useValue: mockGroupService },
        { provide: HomeService, useValue: mockHomeService },
        { provide: PLATFORM_ID, useValue: 'browser' }
      ],
      schemas: [NO_ERRORS_SCHEMA]
    })
    .overrideComponent(HomeComponent, {
      set: {
        imports: [TranslateModule, RouterLink,
          MockIconComponent],
        schemas: [NO_ERRORS_SCHEMA]
      }
    })
    .compileComponents();
  });

  const createComponent = () => {
    fixture = TestBed.createComponent(HomeComponent);
    component = fixture.componentInstance;
    const translate = TestBed.inject(TranslateService);
    translate.use('en');
    fixture.detectChanges();
  };

  it('should create', () => {
    createComponent();
    expect(component).toBeTruthy();
  });

  it('should redirect to dashboard if authenticated on init', () => {
    mockUserStore.isAuthenticated.set(true);
    const router = TestBed.inject(Router);
    const navigateSpy = vi.spyOn(router, 'navigate');

    createComponent();

    expect(navigateSpy).toHaveBeenCalledWith(['/', 'en', 'dashboard']);
  });

  it('should render stats when available', () => {
    createComponent();
    const compiled = fixture.nativeElement as HTMLElement;
    const statsBoxes = compiled.querySelectorAll('.stats_box');
    expect(statsBoxes.length).toBe(4);
    expect(statsBoxes[0].querySelector('.number')?.textContent).toContain('10');
  });

  it('should navigate to login when creating group and not authenticated', () => {
    createComponent();
    const router = TestBed.inject(Router);
    const navigateSpy = vi.spyOn(router, 'navigate');
    mockUserStore.isAuthenticated.set(false);

    component.createGroup();

    expect(navigateSpy).toHaveBeenCalledWith(['/account/login'], expect.any(Object));
  });

  it('should navigate to group create when authenticated', () => {
    createComponent();
    const router = TestBed.inject(Router);
    const navigateSpy = vi.spyOn(router, 'navigate');
    mockUserStore.isAuthenticated.set(true);

    component.createGroup();

    expect(navigateSpy).toHaveBeenCalledWith(['/', 'en', 'my', 'groups', 'create']);
  });

  it('should render topics if available', () => {
    mockTopicService.getPreview.mockReturnValue(of([{ id: '1', title: 'Topic 1' }]));
    createComponent();

    const compiled = fixture.nativeElement as HTMLElement;
    const topicCards = compiled.querySelectorAll('cos-topic-card');
    expect(topicCards.length).toBe(1);
  });

  it('should render groups if available', () => {
    mockGroupService.getPreview.mockReturnValue(of([{ id: '1', name: 'Group 1' }]));
    createComponent();

    const compiled = fixture.nativeElement as HTMLElement;
    const groupCards = compiled.querySelectorAll('cos-group-card');
    expect(groupCards.length).toBe(1);
  });

  it('should navigate to signup when signup button is clicked', () => {
    createComponent();
    const signupBtn = fixture.debugElement.query(By.css('.btn_big_submit'));
    expect(signupBtn).toBeTruthy();
  });

  it('should have correct link to learn more', () => {
    createComponent();
    const compiled = fixture.nativeElement as HTMLElement;
    const learnMoreLnk = compiled.querySelector('.btn_big_submit_ghost');
    expect(learnMoreLnk?.getAttribute('href')).toBe('https://citizenos.com/about-us/');
  });

  it('should call services with limit 3 when mobile', () => {
    // Mock mobile width
    Object.defineProperty(window, 'innerWidth', { writable: true, configurable: true, value: 500 });

    // We must reset the spy because it might have been called during previous test's instantiation if not careful
    mockTopicService.getPreview.mockClear();
    mockGroupService.getPreview.mockClear();

    createComponent();

    expect(mockTopicService.getPreview).toHaveBeenCalledWith(3);
    expect(mockGroupService.getPreview).toHaveBeenCalledWith(3);
  });

  it('should call services with limit 8 when desktop', () => {
    // Mock desktop width
    Object.defineProperty(window, 'innerWidth', { writable: true, configurable: true, value: 1024 });

    mockTopicService.getPreview.mockClear();
    mockGroupService.getPreview.mockClear();

    createComponent();

    expect(mockTopicService.getPreview).toHaveBeenCalledWith(8);
    expect(mockGroupService.getPreview).toHaveBeenCalledWith(8);
  });
});

import { Component, OnInit, signal, inject, ChangeDetectionStrategy, computed } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { form, required } from '@angular/forms/signals';
import { ActivatedRoute, Router } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';
import { TopicService } from '../../../core/services/topic.service';
import { TopicIdeationService } from '../../../core/services/topic-ideation.service';
import { UploadService } from '../../../core/services/upload.service';
import { NotificationService } from '../../../core/services/notification.service';
import { Topic } from '../../../core/interfaces/topic';
import { Ideation } from '../../../core/interfaces/ideation';
import { StepConfig } from '../../../shared/components/step-navigator/step-navigator.component';
import { CreateWizardShellComponent } from '../../../shared/components/create-wizard-shell/create-wizard-shell.component';
import { StepTopicInfoComponent } from '../topic-create/components/step-topic-info/step-topic-info.component';
import { StepTopicSettingsComponent } from '../topic-create/components/step-topic-settings/step-topic-settings.component';
import { StepIdeationSettingsComponent } from './components/step-ideation-settings/step-ideation-settings.component';
import { StepTopicPreviewComponent } from '../topic-create/components/step-topic-preview/step-topic-preview.component';
import { take, of, forkJoin, catchError, switchMap } from 'rxjs';
import { TopicMemberUser, TopicMemberUserService } from '../../../core/services/topic-member-user.service';
import { TopicInvite, TopicInviteUserService } from '../../../core/services/topic-invite-user.service';
import { GroupMemberTopicService } from '../../../core/services/group-member-topic.service';
import { TopicMemberGroup } from '../../../shared/components/topic-settings-panel/topic-settings-panel.component';
import { DialogService } from '../../../shared/dialog/dialog.service';
import { TopicInviteDialogComponent } from '../topic-view/components/topic-invite-dialog/topic-invite-dialog.component';
import { MemberEditorsPanelComponent } from '../../../shared/components/member-editors-panel/member-editors-panel.component';
import { ConfirmDialogComponent } from '../../../shared/components/confirm-dialog/confirm-dialog.component';
import { PendingChangesComponent } from '../../../core/guards/pending-changes.guard';

export type IdeationCreateStep = 'info' | 'settings' | 'ideation' | 'preview';

@Component({
  selector: 'cos-ideation-create',
  standalone: true,
  imports: [
    TranslateModule,
    CreateWizardShellComponent,
    StepTopicInfoComponent,
    StepTopicSettingsComponent,
    StepIdeationSettingsComponent,
    StepTopicPreviewComponent,
    MemberEditorsPanelComponent
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './ideation-create.component.html',
  styleUrl: './ideation-create.component.scss'
})
export class IdeationCreateComponent implements OnInit, PendingChangesComponent {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private topicService = inject(TopicService);
  private ideationService = inject(TopicIdeationService);
  private uploadService = inject(UploadService);
  private notification = inject(NotificationService);
  private memberUserService = inject(TopicMemberUserService);
  private inviteUserService = inject(TopicInviteUserService);
  private groupMemberTopicService = inject(GroupMemberTopicService);
  private dialog = inject(DialogService);

  readonly steps: StepConfig[] = [
    { key: 'info', label: 'VIEWS.IDEATION_CREATE.CREATE_TAB_1', icon: 'edit' },
    { key: 'settings', label: 'VIEWS.IDEATION_CREATE.CREATE_TAB_2', icon: 'settings' },
    { key: 'ideation', label: 'VIEWS.IDEATION_CREATE.CREATE_TAB_3', icon: 'activity' },
    { key: 'preview', label: 'VIEWS.IDEATION_CREATE.CREATE_TAB_4', icon: 'eye' }
  ];

  currentStep = signal<IdeationCreateStep>('info');
  isLoading = signal(false);
  hasChanges = signal(true);

  topicModel = signal<Partial<Topic>>({
    title: '',
    intro: '',
    description: '<html><head></head><body></body></html>',
    visibility: 'private',
    categories: [],
    status: 'draft'
  });

  topicForm = form(this.topicModel, (path: any) => {
    required(path.title);
  });

  ideationModel = signal<Partial<Ideation>>({
    question: '',
    allowAnonymous: false,
    disableReplies: false
  });

  ideationForm = form(this.ideationModel, (path: any) => {
    required(path.question);
  });

  addedGroups = signal<TopicMemberGroup[]>([]);
  groupsToRemove = signal<TopicMemberGroup[]>([]);

  private membersResource = rxResource<TopicMemberUser[], string | undefined>({
    params: () => this.topicModel().id,
    stream: ({ params: id }: { params: string | undefined }) => {
      if (id) return this.memberUserService.loadItems(id);
      return of([]);
    }
  });
  members = computed(() => this.membersResource.value() ?? []);

  private invitesResource = rxResource<TopicInvite[], string | undefined>({
    params: () => this.topicModel().id,
    stream: ({ params: id }: { params: string | undefined }) => {
      if (id) return this.inviteUserService.loadItems(id);
      return of([]);
    }
  });
  invites = computed(() => this.invitesResource.value() ?? []);

  ngOnInit() {
    const topicId = this.route.snapshot.params['topicId'];
    if (topicId) {
      this.loadExistingTopic(topicId);
    } else {
      this.createEagerly();
    }
  }

  private loadExistingTopic(topicId: string) {
    this.isLoading.set(true);
    this.topicService.get(topicId).subscribe({
      next: (topic) => {
        this.topicModel.set(topic);
        this.membersResource.reload();
        this.invitesResource.reload();
        if (topic.ideationId && topic.ideationId !== 'undefined') {
          console.log('BROWSER CONSOLE: loadExistingTopic fetching ideation:', topic.ideationId);
          this.ideationService.get({ topicId: topic.id, ideationId: topic.ideationId }).subscribe({
            next: (ideation) => {
              console.log('BROWSER CONSOLE: loadExistingTopic got ideation:', ideation.id);
              this.ideationModel.set(ideation);
            },
            error: (err) => { 
              console.log('BROWSER CONSOLE: loadExistingTopic err:', err);
            }
          });
        } else {
          console.log('BROWSER CONSOLE: loadExistingTopic NO ideationId in topic:', topic);
        }
        this.isLoading.set(false);
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_LOAD_FAILED');
      }
    });
  }

  private createEagerly() {
    this.isLoading.set(true);
    const initialPayload = {
      description: '<html><head></head><body></body></html>',
      status: 'draft',
      visibility: 'private'
    };
    this.topicService.save(initialPayload).pipe(
      take(1),
      switchMap((savedTopic) => {
        this.topicModel.set(savedTopic);
        this.membersResource.reload();
        this.invitesResource.reload();
        const ideationData = { ...this.ideationModel(), topicId: savedTopic.id || '', question: ' ' };
        return this.ideationService.save(ideationData);
      })
    ).subscribe({
      next: (savedIdeation) => {
        console.log('BROWSER CONSOLE: CREATED IDEATION ID IS: ' + savedIdeation.id);
        this.ideationModel.set(savedIdeation);
        this.isLoading.set(false);
        this.hasChanges.set(false);
        this.router.navigate([this.topicModel().id], {
          relativeTo: this.route,
          replaceUrl: true
        }).then(() => {
          this.hasChanges.set(true);
        });
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
      }
    });
  }

  onStepChange(step: string) {
    if (this.canNavigateTo(step)) {
      this.currentStep.set(step as IdeationCreateStep);
    }
    if (step === 'preview') {
      this.loadDescription();
    }
  }

  private loadDescription() {
    const id = this.topicModel().id;
    if (!id) return;

    this.topicService.readDescription(id).pipe(take(1)).subscribe({
      next: (topic) => {
        this.topicModel.update((t: any) => ({ ...t, description: topic.description }));
      }
    });
  }

  canNavigateTo(step: string): boolean {
    if (step === 'info') return true;
    if (!this.topicModel().title) return false;
    if (step === 'preview' && !this.ideationModel().question) return false;
    return true;
  }

  isFooterNextDisabled(): boolean {
    if (this.currentStep() === 'info') return !this.topicModel().title;
    if (this.currentStep() === 'ideation') return !this.ideationModel().question;
    return false;
  }

  handleFooterContinue() {
    switch (this.currentStep()) {
      case 'info': this.saveToSettings(); break;
      case 'settings': this.saveGroupsAndContinue(); break;
      case 'ideation': this.currentStep.set('preview'); break;
      case 'preview': this.onPublish(); break;
    }
  }

  private saveGroupsAndContinue() {
    const topicId = this.topicModel().id;
    if (!topicId) return;

    this.isLoading.set(true);
    const addOps = this.addedGroups().map(g => this.groupMemberTopicService.addTopic(g.id, topicId, g.level || 'read'));
    const removeOps = this.groupsToRemove().map(g => this.groupMemberTopicService.removeTopicFromGroup(g.id, topicId));

    forkJoin([...addOps, ...removeOps, this.topicService.patch(this.topicModel() as any)]).pipe(
      catchError(() => of(null))
    ).subscribe(() => {
      this.isLoading.set(false);
      this.groupsToRemove.set([]);
      this.onStepChange('ideation');
    });
  }

  handleFooterBack() {
    const order = this.steps.map(s => s.key);
    const idx = order.indexOf(this.currentStep());
    if (idx > 0) this.currentStep.set(order[idx - 1] as IdeationCreateStep);
  }

  onTopicUpdate(updates: Partial<Topic>) {
    this.topicModel.update((t: any) => ({ ...t, ...updates }));
    if (updates.id) {
      this.membersResource.reload();
      this.invitesResource.reload();
    }
  }

  onIdeationUpdate(updates: Partial<Ideation>) {
    this.ideationModel.update((i: any) => ({ ...i, ...updates }));
  }

  onGroupsAdded(groups: TopicMemberGroup[]) {
    this.addedGroups.set(groups);
  }

  onGroupRemoved(group: TopicMemberGroup) {
    this.addedGroups.update(gs => gs.filter(g => g.id !== group.id));
    this.groupsToRemove.update(gs => [...gs, group]);
  }

  inviteEditors() {
    const topic = this.topicModel();
    if (topic.id) {
      this.dialog.open(TopicInviteDialogComponent, {
        data: { topic: topic as Topic, allowedLevels: ['edit', 'admin'] }
      }).afterClosed().subscribe(() => {
        this.membersResource.reload();
        this.invitesResource.reload();
      });
    } else {
      this.notification.showRaw('info', 'VIEWS.TOPIC_CREATE.SAVE_FIRST_TO_INVITE');
    }
  }

  saveToSettings() {
    const t = this.topicModel();
    if (!t.id) {
      this.createEagerly();
      return;
    }

    this.isLoading.set(true);
    this.topicService.patch(t).subscribe({
      next: (updated) => {
        this.topicModel.set(updated);
        this.isLoading.set(false);
        this.onStepChange('settings');
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
      }
    });
  }

  saveAsDraft() {
    const t = this.topicModel();
    if (!t.id) return;
    this.isLoading.set(true);
    this.topicService.patch(t).subscribe({
      next: () => {
        const payload = { ...this.ideationModel(), topicId: t.id || '' };
        if (payload.id && payload.id !== 'undefined') {
          this.ideationService.update(payload).pipe(take(1)).subscribe();
        } else if (payload.question && payload.question.trim().length > 0) {
          this.ideationService.save(payload).pipe(take(1)).subscribe();
        }
        this.isLoading.set(false);
        this.notification.showRaw('success', 'VIEWS.TOPIC_EDIT.NOTIFICATION_SUCCESS_MESSAGE');
        this.hasChanges.set(false);
        this.router.navigate(['/topics', t.id]);
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
      }
    });
  }

  onPublish() {
    const t = this.topicModel();
    if (!t.id) return;
    this.isLoading.set(true);
    this.topicService.patch({ ...t, status: 'ideation' }).subscribe({
      next: (savedTopic) => {
        const payload = { ...this.ideationModel(), topicId: t.id || '' };
        console.log('BROWSER CONSOLE: onPublish payload.id is:', payload.id);
        const request$ = payload.id && payload.id !== 'undefined'
          ? this.ideationService.update(payload)
          : this.ideationService.save(payload);

        request$.pipe(take(1)).subscribe({
          next: () => {
            this.isLoading.set(false);
            this.notification.showRaw('success', 'VIEWS.TOPIC_CREATE.NOTIFICATION_SUCCESS_MESSAGE');
            this.hasChanges.set(false);
            this.dialog.open(TopicInviteDialogComponent, {
              data: { topic: savedTopic }
            }).afterClosed().subscribe(() => {
              this.router.navigate(['/topics', savedTopic.id]);
            });
          },
          error: () => {
            this.isLoading.set(false);
            this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_PUBLISH_FAILED');
          }
        });
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_PUBLISH_FAILED');
      }
    });
  }

  doDeleteTopic() {
    const topicId = this.topicModel().id;
    if (!topicId) return;

    const dialogRef = this.dialog.open(ConfirmDialogComponent, {
      data: {
        level: 'delete',
        heading: 'MODALS.TOPIC_DELETE_CONFIRM_HEADING',
        title: 'MODALS.TOPIC_DELETE_CONFIRM_TXT_ARE_YOU_SURE',
        description: 'MODALS.TOPIC_DELETE_CONFIRM_TXT_NO_UNDO',
        points: ['MODALS.TOPIC_DELETE_CONFIRM_TXT_TOPIC_DELETED', 'MODALS.TOPIC_DELETE_CONFIRM_TXT_DISCUSSION_DELETED', 'MODALS.TOPIC_DELETE_CONFIRM_TXT_TOPIC_REMOVED_FROM_GROUPS'],
        confirmBtn: 'MODALS.TOPIC_DELETE_CONFIRM_YES',
        closeBtn: 'MODALS.TOPIC_DELETE_CONFIRM_NO'
      }
    });

    dialogRef.afterClosed().pipe(take(1)).subscribe(result => {
      if (result === true) {
        this.isLoading.set(true);
        this.topicService.delete({ id: topicId }).pipe(take(1)).subscribe({
          next: () => {
            this.isLoading.set(false);
            this.hasChanges.set(false);
            this.router.navigate(['/my/topics']);
          },
          error: () => {
            this.isLoading.set(false);
            this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
          }
        });
      }
    });
  }

  hasUnsavedChanges(): boolean {
    return this.hasChanges();
  }

  removeChanges() {
    const topicId = this.topicModel().id;
    if (topicId) {
      this.topicService.delete({ id: topicId }).pipe(take(1)).subscribe();
    }
  }
}

import { vi, describe, it, expect, beforeEach } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';

@Component({ template: '', standalone: true })
class EmptyComponent {}
import { TopicService } from '../../../core/services/topic.service';
import { UploadService } from '../../../core/services/upload.service';
import { NotificationService } from '../../../core/services/notification.service';
import { TopicMemberUserService } from '../../../core/services/topic-member-user.service';
import { TopicInviteUserService } from '../../../core/services/topic-invite-user.service';
import { TopicDiscussionService } from '../../../core/services/topic-discussion.service';
import { GroupMemberTopicService } from '../../../core/services/group-member-topic.service';
import { DialogService } from '../../../shared/dialog/dialog.service';
import { TopicCreateComponent } from './topic-create.component';
import { of } from 'rxjs';
import { GroupDetailService } from '../../../core/services/group-detail.service';
import { Router, ActivatedRoute } from '@angular/router';

const mockTopic = { id: 'new-id', title: '', visibility: 'private', status: 'draft', categories: [] };
const mockTopicService = { save: vi.fn(), patch: vi.fn(), get: vi.fn() };
const mockUploadService = { upload: vi.fn() };
const mockNotificationService = { showRaw: vi.fn(), success: vi.fn() };
const mockMemberUserService = { loadItems: vi.fn() };
const mockInviteUserService = { loadItems: vi.fn() };
const mockDiscussionService = { get: vi.fn(), create: vi.fn(), update: vi.fn() };
const mockGroupMemberTopicService = { addTopic: vi.fn(), removeTopicFromGroup: vi.fn() };
const mockDialogService = { open: vi.fn() };
const mockGroup = { id: 'g1', name: 'Test Group', visibility: 'private' };
const mockGroupDetailService = {
  loadGroup: vi.fn().mockReturnValue(of(mockGroup)),
  get: vi.fn().mockReturnValue(of(mockGroup))
};

function setupProviders() {
  TestBed.configureTestingModule({
    imports: [TranslateModule.forRoot()],
    providers: [
      provideRouter([{ path: 'topics/:id', component: EmptyComponent }]),
      { provide: TopicService, useValue: mockTopicService },
      { provide: UploadService, useValue: mockUploadService },
      { provide: NotificationService, useValue: mockNotificationService },
      { provide: TopicMemberUserService, useValue: mockMemberUserService },
      { provide: TopicInviteUserService, useValue: mockInviteUserService },
      { provide: TopicDiscussionService, useValue: mockDiscussionService },
      { provide: GroupMemberTopicService, useValue: mockGroupMemberTopicService },
      { provide: DialogService, useValue: mockDialogService },
      { provide: GroupDetailService, useValue: mockGroupDetailService }
    ]
  });
}

describe('TopicCreateComponent (business logic)', () => {
  let component: TopicCreateComponent;

  beforeEach(() => {
    vi.clearAllMocks();
    mockTopicService.save.mockReturnValue(of(mockTopic));
    mockTopicService.patch.mockReturnValue(of({ ...mockTopic, status: 'inProgress' }));
    mockUploadService.upload.mockReturnValue(of(null));

    mockDiscussionService.create.mockReturnValue(of({ id: 'disc-1', question: '', deadline: null }));
    mockDiscussionService.update.mockReturnValue(of({ id: 'disc-1', question: '', deadline: null }));
    mockGroupMemberTopicService.addTopic.mockReturnValue(of(null));
    mockGroupMemberTopicService.removeTopicFromGroup.mockReturnValue(of(null));
    mockDialogService.open.mockReturnValue({ afterClosed: () => of(true) });
    setupProviders();
    component = TestBed.runInInjectionContext(() => new TopicCreateComponent());
  });

  it('should start at info step', () => {
    expect(component.currentStep()).toBe('info');
  });

  it('canNavigateTo info always returns true', () => {
    expect(component.canNavigateTo('info')).toBe(true);
  });

  it('canNavigateTo settings requires title', () => {
    expect(component.canNavigateTo('settings')).toBe(false);
    component.onTopicUpdate({ title: 'New Topic' });
    expect(component.canNavigateTo('settings')).toBe(true);
  });

  it('saveToSettings creates topic if none exists', () => {
    component.onTopicUpdate({ title: 'Test' });
    component.saveToSettings();
    expect(mockTopicService.save).toHaveBeenCalled();
  });

  it('saveToSettings skips save if topic already has id', () => {
    mockTopicService.patch.mockReturnValue(of({ id: 'existing-id', title: 'Test', status: 'inProgress' }));
    component.topicModel.set({ id: 'existing-id', title: 'Test' });
    component.saveToSettings();
    expect(mockTopicService.save).not.toHaveBeenCalled();
    expect(component.currentStep()).toBe('settings');
  });

  it('saveAsDraft calls patch and shows success notification', () => {
    component.topicModel.set({ id: 'topic-1', title: 'Draft Topic' });
    component.saveAsDraft();
    expect(mockTopicService.patch).toHaveBeenCalled();
    expect(mockNotificationService.showRaw).toHaveBeenCalledWith('success', expect.any(String));
  });

  it('publishTopic calls patch with status inProgress when topic has id', () => {
    component.topicModel.set({ title: 'New Topic', id: 'topic-1' });
    component.publishTopic();
    expect(mockTopicService.patch).toHaveBeenCalledWith(expect.objectContaining({ status: 'inProgress' }));
  });

  it('inviteEditors opens dialog', () => {
    component.topicModel.set({ id: 'topic-1', title: 'Test' });
    component.inviteEditors();
    expect(mockDialogService.open).toHaveBeenCalled();
  });

  it('onGroupsAdded updates signal', () => {
    const groups = [{ id: 'g1', name: 'Group 1' }];
    component.onGroupsAdded(groups);
    expect(component.addedGroups()).toEqual(groups);
  });

  it('shows loading overlay when isLoading is true', () => {
    const fixture = TestBed.createComponent(TopicCreateComponent);
    fixture.componentInstance.isLoading.set(true);
    fixture.detectChanges();
    const overlay = fixture.nativeElement.querySelector('.loading-overlay');
    expect(overlay).toBeTruthy();
  });

  it('shows error notification when createTopicEagerly fails', () => {
    mockTopicService.save.mockReturnValue({
      pipe: () => ({
        subscribe: (callbacks: any) => callbacks.error()
      })
    });

    component.ngOnInit();
    expect(mockNotificationService.showRaw).toHaveBeenCalledWith('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
  });

  it('should initialize isCreatedFromGroup and load group when groupId query param is present', () => {
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({
      imports: [TranslateModule.forRoot()],
      providers: [
        { provide: ActivatedRoute, useValue: {
            snapshot: { paramMap: { get: () => null } },
            queryParams: of({ groupId: 'group-123' })
          }
        },
        { provide: Router, useValue: { navigate: vi.fn().mockResolvedValue(true) } },
        { provide: TopicService, useValue: mockTopicService },
        { provide: UploadService, useValue: mockUploadService },
        { provide: NotificationService, useValue: mockNotificationService },
        { provide: TopicMemberUserService, useValue: mockMemberUserService },
        { provide: TopicInviteUserService, useValue: mockInviteUserService },
        { provide: TopicDiscussionService, useValue: mockDiscussionService },
        { provide: GroupMemberTopicService, useValue: mockGroupMemberTopicService },
        { provide: DialogService, useValue: mockDialogService },
        { provide: GroupDetailService, useValue: mockGroupDetailService }
      ]
    });

    const comp = TestBed.runInInjectionContext(() => new TopicCreateComponent());
    comp.ngOnInit();

    expect(comp.isCreatedFromGroup()).toBe(true);
    expect(mockGroupDetailService.loadGroup).toHaveBeenCalledWith('group-123');
    expect(comp.addedGroups().length).toBe(1);
    expect(comp.addedGroups()[0].id).toBe('g1');
    expect(comp.topicModel().visibility).toBe('private');
  });
});

import { IconComponent } from '../../../shared/components/icon/icon.component';
import { Component, signal, inject, ChangeDetectionStrategy, OnInit, computed } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { Router, ActivatedRoute } from '@angular/router';
import { form, required } from '@angular/forms/signals';
import { TopicService } from '../../../core/services/topic.service';
import { UploadService } from '../../../core/services/upload.service';
import { NotificationService } from '../../../core/services/notification.service';
import { TopicMemberUser, TopicMemberUserService } from '../../../core/services/topic-member-user.service';
import { TopicInvite, TopicInviteUserService } from '../../../core/services/topic-invite-user.service';
import { TopicDiscussionService } from '../../../core/services/topic-discussion.service';
import { Topic } from '../../../core/interfaces/topic';
import { Discussion, DiscussionData } from '../../../core/interfaces/discussion';
import { StepConfig } from '../../../shared/components/step-navigator/step-navigator.component';
import { CreateWizardShellComponent } from '../../../shared/components/create-wizard-shell/create-wizard-shell.component';
import { StepTopicInfoComponent } from './components/step-topic-info/step-topic-info.component';
import { StepTopicSettingsComponent } from './components/step-topic-settings/step-topic-settings.component';
import { StepTopicDiscussionComponent } from './components/step-topic-discussion/step-topic-discussion.component';
import { StepTopicPreviewComponent } from './components/step-topic-preview/step-topic-preview.component';
import { MemberEditorsPanelComponent } from '../../../shared/components/member-editors-panel/member-editors-panel.component';
import { switchMap, of, catchError, forkJoin, take, Observable, map } from 'rxjs';
import { GroupMemberTopicService } from '../../../core/services/group-member-topic.service';
import { TopicMemberGroup } from '../../../shared/components/topic-settings-panel/topic-settings-panel.component';
import { DialogService } from '../../../shared/dialog/dialog.service';
import { TopicInviteDialogComponent } from '../topic-view/components/topic-invite-dialog/topic-invite-dialog.component';
import { ConfirmDialogComponent } from '../../../shared/components/confirm-dialog/confirm-dialog.component';
import { GroupDetailService } from '../../../core/services/group-detail.service';
import { PendingChangesComponent } from '../../../core/guards/pending-changes.guard';

export type TopicCreateStep = 'info' | 'settings' | 'discussion' | 'preview';

@Component({
  selector: 'cos-topic-create',
  standalone: true,
  imports: [
    TranslateModule,
    CreateWizardShellComponent,
    StepTopicInfoComponent,
    StepTopicSettingsComponent,
    StepTopicDiscussionComponent,
    StepTopicPreviewComponent,
    MemberEditorsPanelComponent,
    IconComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './topic-create.component.html',
  styleUrl: './topic-create.component.scss'
})
export class TopicCreateComponent implements OnInit, PendingChangesComponent {
  private topicService = inject(TopicService);
  private uploadService = inject(UploadService);
  private memberUserService = inject(TopicMemberUserService);
  private inviteUserService = inject(TopicInviteUserService);
  private groupMemberTopicService = inject(GroupMemberTopicService);
  private discussionService = inject(TopicDiscussionService);
  private notification = inject(NotificationService);
  private router = inject(Router);
  private route = inject(ActivatedRoute);
  private dialog = inject(DialogService);
  private groupDetailService = inject(GroupDetailService);
  private translate = inject(TranslateService);

  topicModel = signal<Partial<Topic>>({
    title: '',
    intro: '',
    description: '<html><head></head><body></body></html>',
    visibility: 'private',
    categories: [],
    status: 'draft',
    hashtag: null
  });

  topicForm = form(this.topicModel, (path: any) => {
    required(path.title);
  });

  discussion = signal<DiscussionData>({ question: '', deadline: null });
  imageFile = signal<File | null>(null);
  isLoading = signal(false);
  currentStep = signal<TopicCreateStep>('info');
  isCreatedFromGroup = signal(false);
  showHelp = signal(true);
  hasChanges = signal(true);

  addedGroups = signal<TopicMemberGroup[]>([]);
  groupsToRemove = signal<TopicMemberGroup[]>([]);

  membersResource = rxResource<TopicMemberUser[], string | undefined>({
    params: () => this.topicModel().id,
    stream: ({ params: id }: { params: string | undefined }) => id ? this.memberUserService.loadItems(id) : of([])
  });
  members = computed(() => this.membersResource.value() ?? []);

  invitesResource = rxResource<TopicInvite[], string | undefined>({
    params: () => this.topicModel().id,
    stream: ({ params: id }: { params: string | undefined }) => id ? this.inviteUserService.loadItems(id) : of([])
  });
  invites = computed(() => this.invitesResource.value() ?? []);

  readonly steps: StepConfig[] = [
    { key: 'info', label: 'VIEWS.TOPIC_CREATE.CREATE_TAB_1', icon: 'edit' },
    { key: 'settings', label: 'VIEWS.TOPIC_CREATE.CREATE_TAB_2', icon: 'settings' },
    { key: 'discussion', label: 'VIEWS.TOPIC_CREATE.CREATE_TAB_3', icon: 'comment' },
    { key: 'preview', label: 'VIEWS.TOPIC_CREATE.CREATE_TAB_4', icon: 'eye' }
  ];

  ngOnInit() {
    const topicId = this.route.snapshot.paramMap.get('topicId');

    this.route.queryParams.pipe(take(1)).subscribe({
      next: (params) => {
        const grId = params['groupId'];
        if (grId) {
          this.isCreatedFromGroup.set(true);
          this.groupDetailService.loadGroup(grId).subscribe({
            next: (group) => {
              this.onGroupsAdded([{ ...group, level: 'read' }]);
              this.onTopicUpdate({ visibility: 'private' });
            }
          });
        }
      }
    });

    if (topicId) {
      this.loadExistingTopic(topicId);
    } else {
      this.createTopicEagerly();
    }
  }

  private loadExistingTopic(topicId: string) {
    this.isLoading.set(true);
    this.topicService.get(topicId).subscribe({
      next: (topic) => {
        this.topicModel.set(topic);
        this.membersResource.reload();
        this.invitesResource.reload();
        if (topic.discussionId) {
          this.discussionService.get(topicId, topic.discussionId).subscribe({
            next: (d) => this.discussion.set({ question: d.question, deadline: d.deadline }),
            error: () => { /* intentionally empty */ }
          });
        }
        this.isLoading.set(false);
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_LOAD_FAILED');
      }
    });
  }

  private createTopicEagerly() {
    this.isLoading.set(true);
    const initialPayload = {
      description: '<html><head></head><body></body></html>',
      status: 'draft',
      visibility: 'private'
    };
    this.topicService.save(initialPayload).pipe(take(1)).subscribe({
      next: (savedTopic) => {
        this.topicModel.set(savedTopic);
        this.membersResource.reload();
        this.invitesResource.reload();
        this.isLoading.set(false);
        // Update URL to include topicId without triggering navigation
        this.hasChanges.set(false);
        this.router.navigate([savedTopic.id], {
          relativeTo: this.route,
          replaceUrl: true
        }).then(() => {
          this.hasChanges.set(true);
        });
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
      }
    });
  }

  onStepChange(step: string) {
    if (this.canNavigateTo(step)) {
      this.currentStep.set(step as TopicCreateStep);
      if (step === 'preview') {
        this.loadDescription();
      }
    }
  }

  private loadDescription() {
    const id = this.topicModel().id;
    if (!id) return;

    this.topicService.readDescription(id).pipe(take(1)).subscribe({
      next: (topic) => {
        this.topicModel.update(t => ({ ...t, description: topic.description }));
      }
    });
  }

  canNavigateTo(step: string): boolean {
    if (step === 'info') return true;
    return !!this.topicModel().title;
  }

  isFooterNextDisabled(): boolean {
    if (this.currentStep() === 'info') return !this.topicModel().title;
    if (this.currentStep() === 'discussion') return !this.discussion().question;
    return false;
  }

  handleFooterContinue() {
    switch (this.currentStep()) {
      case 'info': this.saveToSettings(); break;
      case 'settings': this.saveGroupsAndContinue(); break;
      case 'discussion': this.transitionToPreview(); break;
      case 'preview': this.publishTopic(); break;
    }
  }

  private saveGroupsAndContinue() {
    const topicId = this.topicModel().id;
    if (!topicId) return;

    this.isLoading.set(true);
    const addOps = this.addedGroups().map(g => this.groupMemberTopicService.addTopic(g.id, topicId, g.level || 'read'));
    const removeOps = this.groupsToRemove().map(g => this.groupMemberTopicService.removeTopicFromGroup(g.id, topicId));

    forkJoin([...addOps, ...removeOps, this.topicService.patch(this.topicModel())]).pipe(
      catchError(() => of(null))
    ).subscribe(() => {
      this.isLoading.set(false);
      this.groupsToRemove.set([]);
      this.onStepChange('discussion');
    });
  }

  handleFooterBack() {
    const order = this.steps.map(s => s.key);
    const idx = order.indexOf(this.currentStep());
    if (idx > 0) this.currentStep.set(order[idx - 1] as TopicCreateStep);
  }

  onTopicUpdate(updates: Partial<Topic>) {
    this.topicModel.update(t => ({ ...t, ...updates }));
    if (updates.id) {
      this.membersResource.reload();
      this.invitesResource.reload();
    }
  }

  onImageFileUpdate(file: File | null) {
    this.imageFile.set(file);
  }

  onGroupsAdded(groups: TopicMemberGroup[]) {
    this.addedGroups.set(groups);
  }

  onGroupRemoved(group: TopicMemberGroup) {
    this.addedGroups.update(gs => gs.filter(g => g.id !== group.id));
    this.groupsToRemove.update(gs => [...gs, group]);
  }

  saveToSettings() {
    const t = this.topicModel();
    if (!t.id) {
      // Topic not yet created (e.g. eager create failed) — create now
      this.createTopicEagerly();
      return;
    }

    const patchAndUpload$ = this.topicService.patch(t).pipe(
      switchMap((updated) => {
        this.topicModel.set(updated);
        if (this.imageFile()) {
          const path = `/api/users/self/topics/${updated.id}/upload`;
          return this.uploadService.upload<{ imageUrl?: string; link?: string; id?: string }>(path, this.imageFile()!).pipe(
            map((uploaded) => {
              if (uploaded) {
                const imageUrl = uploaded.imageUrl || uploaded.link;
                if (imageUrl) {
                  this.topicModel.update(current => ({ ...current, imageUrl }));
                } else if (uploaded.id) {
                  this.topicModel.set(uploaded);
                }
              }
              return uploaded;
            })
          );
        }
        return of(null);
      }),
      catchError(() => {
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
        return of(null);
      })
    );

    this.isLoading.set(true);
    patchAndUpload$.subscribe(() => {
      this.isLoading.set(false);
      this.onStepChange('settings');
    });
  }

  transitionToPreview() {
    const t = this.topicModel();
    const disc = this.discussion();

    if (!t.id || !disc.question) {
      this.currentStep.set('preview');
      return;
    }

    this.isLoading.set(true);
    const save$ = t.discussionId
      ? this.discussionService.update(t.id, t.discussionId, disc)
      : this.discussionService.create(t.id, disc);

    save$.pipe(catchError(() => of(null))).subscribe((d) => {
      if (d) this.topicModel.update(current => ({ ...current, discussionId: d.id }));
      this.isLoading.set(false);
      this.currentStep.set('preview');
    });
  }

  private saveGroups(topicId: string): Observable<unknown> {
    const addOps = this.addedGroups().map(g => this.groupMemberTopicService.addTopic(g.id, topicId, g.level || 'read'));
    const removeOps = this.groupsToRemove().map(g => this.groupMemberTopicService.removeTopicFromGroup(g.id, topicId));
    if (addOps.length === 0 && removeOps.length === 0) {
      return of(null);
    }
    return forkJoin([...addOps, ...removeOps]).pipe(
      catchError(() => of(null))
    );
  }

  saveAsDraft() {
    const t = this.topicModel();
    if (!t.id) {
      this.notification.showRaw('info', 'VIEWS.TOPIC_CREATE.SAVE_FIRST_TO_INVITE');
      return;
    }

    this.isLoading.set(true);
    this.topicService.patch(t).pipe(
      switchMap((savedTopic) => {
        this.topicModel.set(savedTopic);
        return this.saveGroups(savedTopic.id!);
      })
    ).subscribe({
      next: () => {
        this.isLoading.set(false);
        this.groupsToRemove.set([]);
        this.notification.showRaw('success', 'VIEWS.TOPIC_EDIT.NOTIFICATION_SUCCESS_MESSAGE');
        this.hasChanges.set(false);
        this.router.navigate(['/', this.translate.currentLang || 'en', 'topics', this.topicModel().id]);
      },
      error: () => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
      }
    });
  }

  publishTopic() {
    this.isLoading.set(true);
    const t = this.topicModel();
    const disc = this.discussion();
    const isNewOrDraft = t.status === 'draft';

    const topicSave$ = t.id
      ? this.topicService.patch({ ...t, status: 'inProgress', visibility: 'public' })
      : this.topicService.save({ ...t, status: 'inProgress', visibility: 'public' });

    topicSave$.pipe(
      switchMap((savedTopic) => {
        this.topicModel.set(savedTopic);
        const groupsSave$ = this.saveGroups(savedTopic.id!);
        const discSave$: Observable<Discussion | null> = disc.question
          ? (savedTopic.discussionId
              ? this.discussionService.update(savedTopic.id!, savedTopic.discussionId, disc)
              : this.discussionService.create(savedTopic.id!, disc))
          : of(null);

        return forkJoin({
          topic: of(savedTopic),
          groups: groupsSave$,
          discussion: discSave$.pipe(catchError(() => of(null)))
        });
      }),
      catchError(() => {
        this.isLoading.set(false);
        this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_PUBLISH_FAILED');
        return of(null);
      })
    ).subscribe((result) => {
      if (!result) return;
      this.isLoading.set(false);
      this.groupsToRemove.set([]);

      const successMessage = isNewOrDraft
        ? 'VIEWS.TOPIC_CREATE.NOTIFICATION_SUCCESS_MESSAGE'
        : 'VIEWS.TOPIC_EDIT.NOTIFICATION_SUCCESS_MESSAGE';

      this.notification.showRaw('success', successMessage);

      this.hasChanges.set(false);
      this.router.navigate(['/', this.translate.currentLang || 'en', 'topics', this.topicModel().id]).then(() => {
        if (isNewOrDraft) {
          this.dialog.open(TopicInviteDialogComponent, {
            data: { topic: this.topicModel() }
          });
        }
      });
    });
  }

  inviteEditors() {
    const topic = this.topicModel();
    if (topic.id) {
      this.dialog.open(TopicInviteDialogComponent, {
        data: { topic: topic as Topic, allowedLevels: ['edit', 'admin'] }
      }).afterClosed().subscribe(() => {
        this.membersResource.reload();
        this.invitesResource.reload();
      });
    } else {
      this.notification.showRaw('info', 'VIEWS.TOPIC_CREATE.SAVE_FIRST_TO_INVITE');
    }
  }

  doDeleteTopic() {
    const topicId = this.topicModel().id;
    if (!topicId) return;

    const dialogRef = this.dialog.open(ConfirmDialogComponent, {
      data: {
        level: 'delete',
        heading: 'MODALS.TOPIC_DELETE_CONFIRM_HEADING',
        title: 'MODALS.TOPIC_DELETE_CONFIRM_TXT_ARE_YOU_SURE',
        description: 'MODALS.TOPIC_DELETE_CONFIRM_TXT_NO_UNDO',
        points: ['MODALS.TOPIC_DELETE_CONFIRM_TXT_TOPIC_DELETED', 'MODALS.TOPIC_DELETE_CONFIRM_TXT_DISCUSSION_DELETED', 'MODALS.TOPIC_DELETE_CONFIRM_TXT_TOPIC_REMOVED_FROM_GROUPS'],
        confirmBtn: 'MODALS.TOPIC_DELETE_CONFIRM_YES',
        closeBtn: 'MODALS.TOPIC_DELETE_CONFIRM_NO'
      }
    });

    dialogRef.afterClosed().pipe(take(1)).subscribe(result => {
      if (result === true) {
        this.isLoading.set(true);
        this.topicService.delete({ id: topicId }).pipe(take(1)).subscribe({
          next: () => {
            this.isLoading.set(false);
            this.hasChanges.set(false);
            this.router.navigate(['/my/topics']);
          },
          error: () => {
            this.isLoading.set(false);
            this.notification.showRaw('error', 'VIEWS.TOPIC_CREATE.ERROR_SAVE_FAILED');
          }
        });
      }
    });
  }

  hasUnsavedChanges(): boolean {
    return this.hasChanges();
  }

  removeChanges() {
    const topicId = this.topicModel().id;
    if (topicId) {
      this.topicService.delete({ id: topicId }).pipe(take(1)).subscribe();
    }
  }
}

